insert into public.benefit_rules (id,name,agency,region_scope,criteria_json,description,source_url,source_key,version,valid_from,valid_until,checked_at,review_due_at,status) values
('00000002-0000-4000-8000-000000000001','당뇨병환자 소모성재료 구입비','국민건강보험공단','["all"]','{"schema_version":1,"diagnosed":true,"additional_requirements":["공단 등록과 처방전, 구입 품목 및 등록업소 요건을 확인해 주세요.","인슐린 투여가 원칙이나 만 19세 미만·임신 중에는 예외가 있어요. 본인 조건은 공단에 확인해 주세요."]}','혈당측정검사지와 채혈침 등 정해진 소모성재료 구입비를 지원하는 제도예요. 지원 품목과 금액은 진단 유형·연령·처방에 따라 달라요.','https://www.nhis.or.kr/static/html/wbma/c/wbmac0208.html','nhis-diabetes-consumables',1,NULL,NULL,'2026-10-21T00:00:00Z','2026-11-21T00:00:00Z','approved'),
('00000002-0000-4000-8000-000000000002','당뇨병 관리기기 구입비','국민건강보험공단','["all"]','{"schema_version":1,"diagnosed":true,"insulin_use":true,"additional_requirements":["제1형 당뇨병의 인정기준과 공단 등록 여부를 확인해 주세요. 제2형은 해당 급여에서 제외돼요.","급여대상 등록 뒤 받은 처방전과 등록 제품·업소, 구입 시점 및 지급 주기를 확인해 주세요."]}','인슐린을 투여하는 등록된 제1형 당뇨병 환자의 연속혈당측정기와 인슐린자동주입기 구입을 지원하는 제도예요.','https://www.nhis.or.kr/static/html/wbma/c/wbmac0230.html','nhis-diabetes-devices',1,NULL,NULL,'2026-10-21T00:00:00Z','2026-11-21T00:00:00Z','approved'),
('00000002-0000-4000-8000-000000000003','고혈압·당뇨병 등록관리사업','질병관리청·사업지역 보건소','["서울","광주","울산","세종","경기","강원","전북","전남","경북","경남","제주"]','{"schema_version":1,"min_age":30,"additional_requirements":["고혈압 또는 당뇨병 진단과 주민등록상 사업지역 거주 여부를 보건소에 확인해 주세요.","같은 시·도라도 일부 시·군·구만 사업지역이에요. 참여 의료기관과 등록 여부를 확인해 주세요.","2026년 9월 30일 사업 개편 계획이 발표됐어요. 현재 지역별 서비스와 의료비 지원 여부는 보건소에서 확인해야 해요."]}','사업지역 주민에게 질환·영양·운동 교육과 상담, 진료 일정 알림을 제공해요. 지역과 연령별 지원 내용은 보건소 확인이 필요해요.','https://www.kdca.go.kr/kdca/3361/subview.do','kdca-diabetes-registration',1,NULL,NULL,'2026-10-21T00:00:00Z','2026-11-21T00:00:00Z','approved');
